tación del servicio de certificación de producto."],"codigoNace":"45825","nace":"28","source":"base"},{"producto":"Duplicadores_de_parqueo_u_otros","clase":"Reglamento_RETIE_resolución_40117","familia":"Duplicadores_de_parqueo_u_otros","familiaArticulo":"","subfamilia":"Duplicadores_de_parqueo_u_otros","articuloAdicional":"","articuloEnsayosMinimos":"","documento":"Resolución 40117 de 02 de abril de 2024 del Ministerio de Minas y Energía de Colombia \" Por la cual se modifica el Reglamento Técnico de Instalaciones Eléctricas- RETIE\" Libro 2. Título 2 - Requisitos generales para los productos utilizados en las instalaciones eléctricas. (Artículo. 2.2.1. Artículo. 2.2.2.) Artículo 2.3.27 Artículo Productos para instalaciones especiales, equipos especiales, minas, túneles y cavernas Artículo 2.3.27.1. Equipos especiales. Duplicadores de parqueo u otros","esquemas":["Esquema 1B RETIE","Esquema 4 RETIE","Esquema 5 RETIE","GMV-RG-19 Términos y condiciones para la prestación del servicio de certificación de producto."],"codigoNace":"45825","nace":"28","source":"base"},{"producto":"Sistemas_contraincendio_(bombas contraincendio,_motor_para_bomba contraincendio_y_su_controlador)._Bomba","clase":"Reglamento_RETIE_resolución_40117","familia":"Sistemas_contraincendio_(bombas contraincendio,_motor_para_bomba contraincendio_y_su_controlador)._Bomba","familiaArticulo":"","subfamilia":"Sistemas_contraincendio_(bombas contraincendio,_motor_para_bomba contraincendio_y_su_controlador)._Bomba","articuloAdicional":"","articuloEnsayosMinimos":"","documento":"Resolución 40117 de 02 de abril de 2024 del Ministerio de Minas y Energía de Colombia \" Por la cual se modifica el Reglamento Técnico de Instalaciones Eléctricas- RETIE\" Libro 2. Título 2 - Requisitos generales para los productos utilizados en las instalaciones eléctricas. (Artículo. 2.2.1. Artículo. 2.2.2.) Artículo 2.3.27 Artículo Productos para instalaciones especiales, equipos especiales, minas, túneles y cavernas Artículo 2.3.27.1. Equipos especiales. Sistemas contraincendio (bombas contraincendio, motor para bomba contraincendio y su controlador). Bomba","esquemas":["Esquema 1B RETIE","Esquema 4 RETIE","Esquema 5 RETIE","GMV-RG-19 Términos y condiciones para la prestación del servicio de certificación de producto."],"codigoNace":"45825","nace":"28","source":"base"}],"productLines":["Reglamento_RETIE_resolución_40117","Reglamento_RETILAP_resolución_40150","Alambre_Grafilado_y_Mallas_Electrosoldadas_Resolucion_0277_de_2015","Alambre_Grafilado_y_Mallas_Electrosoldadas_Resolucion_1019_de_2024","Barras_Corrugadas_Resolución_2003_de_2022","Cascos_Resolución_1080_de_2019","Ítems_Colombia_Resolucion_0686_de_2018","Ítems_Reglamento_Técnico_Ecuatoriano_RTE_INEN_089_Resolución_14371_de_2014","Vajillas_Resolucion_1440_de_2019","Reglamento_Técnico_Ecuatoriano_RTE_INEN_069_1R_Alumbrado_Público","Reglamento_Técnico_Ecuatoriano_RTE_INEN_057_2R","Reglamento_Técnico_Salvadoreño_RTS_29_Productos_Eléctricos","Voluntario"],"defaultProductLine":"Ítems_Colombia_Resolucion_0686_de_2018"}</script>
  <script>
    const DATA = JSON.parse(document.getElementById('app-data').textContent);

    const REGULATORY_STORAGE_KEY = 'constructor_normativo_registros_retie_retilap_v1';
    const REGULATORY_LINES = new Set([
      'Reglamento_RETIE_resolución_40117',
      'Reglamento_RETILAP_resolución_40150'
    ]);
    let regulatoryRecords = [];

    const PHASES = [
      { key: 'OT', label: 'OT' },
      { key: 'VIG_1', label: 'Vigilancia 1' },
      { key: 'VIG_2', label: 'Vigilancia 2' },
      { key: 'RENOVACION', label: 'Renovación' }
    ];

    const STORAGE_KEY = 'constructor_normativo_productos_v2';
    const DEFAULT_PRODUCT_LINE = DATA.defaultProductLine || 'Juguetes_Colombia_Resolucion_0686_de_2018';

    const state = {
      project: {
        referenceType: 'Reglamento técnico nacional',
        productLine: DEFAULT_PRODUCT_LINE,
        projectName: ''
      },
      currentToy: newToy(),
      savedToys: [],
      results: [],
      metrics: null
    };

    const $ = (id) => document.getElementById(id);
    const collator = new Intl.Collator('es', { sensitivity: 'base', numeric: true });

    const familyByNorm = new Map();
    const subfamilyByNorm = new Map();
    const subfamiliesByFamily = new Map();
    const testsBySubfamily = new Map();
    const combosByClass = new Map();

    function newToy(name = '') {
      return {
        id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),
        name,
        subfamilies: []
      };
    }

    function normalizeKey(value) {
      return String(value || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/\s+/g, ' ')
        .trim();
    }

    function uniqueSorted(values) {
      return [...new Set(values.filter(Boolean).map(v => String(v).trim()).filter(Boolean))]
        .sort((a, b) => collator.compare(a, b));
    }

    function humanizeNorm(norm) {
      return String(norm || '')
        .replaceAll('_', ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function currentProductLine() {
      return state.project?.productLine || DEFAULT_PRODUCT_LINE;
    }

    function belongsToCurrentLine(item) {
      return (item?.lineaProducto || DEFAULT_PRODUCT_LINE) === currentProductLine();
    }

    function productLineLabel(line) {
      return humanizeNorm(line);
    }

    function isRegulatoryLine(line = currentProductLine()) {
      return REGULATORY_LINES.has(line);
    }

    function safeNorm(value, fallback = 'SIN_DATO') {
      const clean = String(value || fallback)
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^A-Za-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .replace(/_+/g, '_');
      return clean || fallback;
    }

    function cleanCell(value) {
      return String(value ?? '')
        .replace(/\r/g, '')
        .replace(/\n+/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    }

    function normalizeHeader(value) {
      return normalizeKey(value)
        .replace(/[^a-z0-9]+/g, ' ')
        .trim();
    }

    function parseDelimitedRows(text, delimiter = '\t') {
      const rows = [];
      let row = [];
      let cell = '';
      let inQuotes = false;

      for (let i = 0; i < text.length; i += 1) {
        const ch = text[i];
        const next = text[i + 1];

        if (ch === '"') {
          if (inQuotes && next === '"') {
            cell += '"';
            i += 1;
          } else {
            inQuotes = !inQuotes;
          }
          continue;
        }

        if (!inQuotes && ch === delimiter) {
          row.push(cell);
          cell = '';
          continue;
        }

        if (!inQuotes && (ch === '\n' || ch === '\r')) {
          if (ch === '\r' && next === '\n') i += 1;
          row.push(cell);
          if (row.some(v => cleanCell(v))) rows.push(row);
          row = [];
          cell = '';
          continue;
        }

        cell += ch;
      }

      row.push(cell);
      if (row.some(v => cleanCell(v))) rows.push(row);
      return rows;
    }

    function normalizeRegulatoryRecord(raw, index = 0) {
      const producto = cleanCell(raw.producto || raw.PRODUCTO || raw.Producto || raw.subfamilia || raw.Subfamilia);
      const clase = cleanCell(raw.clase || raw.CLASE || raw.Clase || raw.lineaProducto || currentProductLine());
      const familia = cleanCell(raw.familia || raw.Familia || producto || 'Sin familia');
      const familiaArticulo = cleanCell(raw.familiaArticulo || raw['Familia artículo'] || raw.familia_articulo || raw.numeralFamilia);
      const subfamilia = cleanCell(raw.subfamilia || raw.Subfamilia || producto);
      const articuloAdicional = cleanCell(raw.articuloAdicional || raw['Artículo Adicional'] || raw.observacion || raw.nota);
      const articuloEnsayosMinimos = cleanCell(raw.articuloEnsayosMinimos || raw['Artículo Ensayos mínimos'] || raw.articulo || raw.numeral);
      const documento = cleanCell(raw.documento || raw.DOCUMENTO);
      const codigoNace = cleanCell(raw.codigoNace || raw['Código NACE'] || raw['Codigo NACE'] || raw.codigo_nace || raw.CODIGO_NACE);
      const nace = cleanCell(raw.nace || raw.NACE);
      const esquemas = uniqueSorted(
        Array.isArray(raw.esquemas) ? raw.esquemas : String(raw.esquemas || raw.ESQUEMAS || '').split(/\s*\|\s*|\n+/)
      ).filter(Boolean);

      const lineaProducto = REGULATORY_LINES.has(clase) ? clase : currentProductLine();

      return {
        id: `${safeNorm(lineaProducto)}_${safeNorm(producto || subfamilia)}_${safeNorm(articuloEnsayosMinimos || familiaArticulo || index)}`,
        producto,
        clase: lineaProducto,
        familia,
        familiaArticulo,
        subfamilia,
        articuloAdicional,
        articuloEnsayosMinimos,
        documento,
        esquemas,
        codigoNace,
        nace,
        familiaNorm: safeNorm(familia),
        subfamiliaNorm: safeNorm(subfamilia || producto),
        productoNorm: safeNorm(producto || subfamilia),
        source: raw.source || 'importado'
      };
    }

    function parseRegulatoryTable(text) {
      const rows = parseDelimitedRows(text);
      if (rows.length < 2) return [];

      const headers = rows[0].map(h => cleanCell(h));
      const normalizedHeaders = headers.map(normalizeHeader);
      const records = [];

      rows.slice(1).forEach((cells, rowIndex) => {
        const raw = {};
        const esquemaValues = [];

        cells.forEach((value, index) => {
          const header = normalizedHeaders[index] || '';
          const clean = cleanCell(value);
          if (!clean) return;

          if (header === 'producto') raw.producto = clean;
          else if (header === 'clase') raw.clase = clean;
          else if (header === 'familia') raw.familia = clean;
          else if (header === 'familia articulo') raw.familiaArticulo = clean;
          else if (header === 'subfamilia') raw.subfamilia = clean;
          else if (header === 'articulo adicional') raw.articuloAdicional = clean;
          else if (header === 'articulo ensayos minimos' || header === 'articulo ensayos mínimos') raw.articuloEnsayosMinimos = clean;
          else if (header === 'documento') raw.documento = clean;
          else if (header === 'esquemas' || header === 'esquema') esquemaValues.push(clean);
          else if (header === 'nace') raw.nace = clean;
          else if (header === 'codigo nace' || header === 'código nace') raw.codigoNace = clean;
          else if (!header && index > 0 && ['esquemas', 'esquema'].includes(normalizedHeaders[index - 1])) {
            if (/^\d{4,6}$/.test(clean)) raw.codigoNace = clean;
            else esquemaValues.push(clean);
          }
        });

        raw.esquemas = esquemaValues.flatMap(v => String(v).split(/\n+|;\s*/)).filter(Boolean);
        if (raw.producto || raw.subfamilia) records.push(normalizeRegulatoryRecord(raw, rowIndex));
      });

      return records;
    }

    function dedupeRegulatoryRecords(records) {
      const map = new Map();
      records.forEach(record => {
        const key = normalizeKey([record.clase, record.producto, record.subfamilia, record.articuloEnsayosMinimos].join('|'));
        if (!map.has(key)) {
          map.set(key, record);
          return;
        }
        const current = map.get(key);
        current.esquemas = uniqueSorted([...(current.esquemas || []), ...(record.esquemas || [])]);
        ['documento', 'articuloAdicional', 'codigoNace', 'nace', 'familiaArticulo'].forEach(field => {
          if (!current[field] && record[field]) current[field] = record[field];
        });
      });
      return [...map.values()];
    }

    function loadRegulatoryRecords() {
      let imported = [];
      try {
        imported = JSON.parse(localStorage.getItem(REGULATORY_STORAGE_KEY) || '[]');
      } catch (_) {
        imported = [];
      }
      regulatoryRecords = dedupeRegulatoryRecords([...(DATA.regulatoryArticles || []), ...imported].map(normalizeRegulatoryRecord));
      syncRegulatoryRecordsIntoCatalog();
    }

    function saveImportedRegulatoryRecords(records) {
      const existing = regulatoryRecords.filter(r => r.source === 'importado');
      const merged = dedupeRegulatoryRecords([...existing, ...records.map(r => ({ ...r, source: 'importado' }))]);
      localStorage.setItem(REGULATORY_STORAGE_KEY, JSON.stringify(merged));
      loadRegulatoryRecords();
    }

    function syncRegulatoryRecordsIntoCatalog() {
      const knownSubs = new Set(DATA.subfamilies.map(s => s.subfamiliaNorm));
      regulatoryRecords.forEach(record => {
        if (!knownSubs.has(record.subfamiliaNorm)) {
          DATA.subfamilies.push({
            familia: record.familia || record.producto || 'RETIE/RETILAP',
            familiaNorm: record.familiaNorm,
            subfamilia: record.subfamilia || record.producto,
            subfamiliaNorm: record.subfamiliaNorm,
            cantidadEnsayosBase: 0,
            lineaProducto: record.clase
          });
          knownSubs.add(record.subfamiliaNorm);
        }
      });
    }

    function regulatoryRecordsForSubfamily(subNorm) {
      const wanted = normalizeKey(subNorm);
      const wantedLabel = normalizeKey(subLabel(subNorm));
      return regulatoryRecords.filter(record => {
        if (record.clase !== currentProductLine()) return false;
        return [
          record.subfamiliaNorm,
          record.productoNorm,
          record.subfamilia,
          record.producto
        ].some(value => normalizeKey(value) === wanted || normalizeKey(value) === wantedLabel);
      });
    }

    function renderRegulatoryImportSummary() {
      const panel = $('regulatoryImportSummary');
      if (!panel) return;
      const current = regulatoryRecords.filter(r => r.clase === currentProductLine());
      const imported = current.filter(r => r.source === 'importado').length;
      panel.innerHTML = `
        <strong>Base activa para ${escapeHtml(productLineLabel(currentProductLine()))}</strong><br>
        ${current.length} producto(s)/artículo(s) cargado(s). ${imported} provienen de importación local y ${current.length - imported} de la base precargada.
        <div class="mini">Incluye producto, familia, artículo/numeral, observaciones, documento, esquemas, código NACE y NACE. Los datos importados se guardan en el navegador mediante localStorage; en la versión web con base de datos, esta misma tabla debe migrarse a una tabla de productos normativos.</div>
      `;
    }

    function subLabel(norm) {
      return subfamilyByNorm.get(norm)?.subfamilia || humanizeNorm(norm);
    }

    function familyLabel(norm) {
      return familyByNorm.get(norm)?.familia || humanizeNorm(norm);
    }

    function escapeHtml(value) {
      return String(value ?? '')
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&#039;');
    }

    function phaseBadges(row) {
      const active = PHASES.filter(p => row[p.key]).map(p => p.label);
      if (!active.length) return '<span class="muted">Sin fase marcada</span>';
      return active.map(p => `<span class="pill ok">${escapeHtml(p)}</span>`).join(' ');
    }

    function joinSmall(values, separator = ' · ') {
      const list = Array.isArray(values) ? values : [];
      return list.length ? escapeHtml(list.join(separator)) : '<span class="muted">—</span>';
    }

    function initMaps() {
      familyByNorm.clear();
      subfamilyByNorm.clear();
      subfamiliesByFamily.clear();
      testsBySubfamily.clear();
      combosByClass.clear();

      DATA.subfamilies.forEach(item => {
        familyByNorm.set(item.familiaNorm, item);
        subfamilyByNorm.set(item.subfamiliaNorm, item);
        if (!subfamiliesByFamily.has(item.familiaNorm)) subfamiliesByFamily.set(item.familiaNorm, []);
        subfamiliesByFamily.get(item.familiaNorm).push(item);
      });

      for (const list of subfamiliesByFamily.values()) {
        list.sort((a, b) => collator.compare(a.subfamilia, b.subfamilia));
      }

      DATA.tests.forEach(item => {
        if (!testsBySubfamily.has(item.subfamiliaNorm)) testsBySubfamily.set(item.subfamiliaNorm, []);
        testsBySubfamily.get(item.subfamiliaNorm).push(item);
      });

      DATA.combinations.forEach(combo => {
        if (!combosByClass.has(combo.idClasificacion)) combosByClass.set(combo.idClasificacion, []);
        combosByClass.get(combo.idClasificacion).push(combo);
      });
    }

    function loadState() {
      try {
        const raw = localStorage.getItem(STORAGE_KEY);
        if (!raw) return;
        const parsed = JSON.parse(raw);
        if (parsed.project) state.project = { ...state.project, ...parsed.project };
        if (Array.isArray(parsed.savedToys)) state.savedToys = parsed.savedToys;
        if (parsed.currentToy && Array.isArray(parsed.currentToy.subfamilies)) state.currentToy = parsed.currentToy;
      } catch (error) {
        console.warn('No se pudo cargar estado local:', error);
      }
    }

    function persistState() {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify({
          project: state.project,
          currentToy: state.currentToy,
          savedToys: state.savedToys
        }));
      } catch (error) {
        console.warn('No se pudo guardar estado local:', error);
      }
    }

    function renderStats() {
      const stats = DATA.meta.stats;
      const items = [
        [stats.familias, 'clases / familias'],
        [stats.subfamiliasBase, 'subfamilias base'],
        [stats.combinacionesClasificacion, 'combinaciones de clase'],
        [stats.combinacionesSubfamilia, 'subcombinaciones'],
        [stats.ensayosBaseUnicos, 'ensayos base únicos'],
        [stats.registrosBase, 'registros base']
      ];

      $('stats').innerHTML = items.map(([value, label]) => `
        <div class="stat">
          <strong>${escapeHtml(value)}</strong>
          <span>${escapeHtml(label)}</span>
        </div>
      `).join('');

      $('metaNotes').innerHTML = [
        DATA.meta.fases,
        DATA.meta.notaMaterial,
        DATA.meta.deduplicacion,
        DATA.meta.notaVajillas,
        DATA.meta.notaRETIE_RETILAP
      ].filter(Boolean).map(note => `<span class="pill neutral">${escapeHtml(note)}</span>`).join('');
    }

    function renderProjectConfig() {
      $('referenceTypeSelect').value = state.project.referenceType || 'Reglamento técnico nacional';
      $('productLineSelect').innerHTML = (DATA.productLines || [DEFAULT_PRODUCT_LINE]).map(line => `
        <option value="${escapeHtml(line)}">${escapeHtml(productLineLabel(line))}</option>
      `).join('');
      $('productLineSelect').value = currentProductLine();
      $('projectNameInput').value = state.project.projectName || '';

      const families = [...subfamiliesByFamily.entries()]
        .filter(([, subs]) => subs.some(belongsToCurrentLine))
        .length;
      const subfamilies = DATA.subfamilies.filter(belongsToCurrentLine).length;
      const tests = DATA.tests.filter(belongsToCurrentLine).length;
      const isReg = isRegulatoryLine();
      const regCount = regulatoryRecords.filter(r => r.clase === currentProductLine()).length;

      $('projectConfigSummary').innerHTML = `
        <strong>Configuración activa</strong><br>
        ${escapeHtml(state.project.referenceType || '—')} · ${escapeHtml(productLineLabel(currentProductLine()))}
        <div class="mini">
          ${families} familia(s), ${subfamilies} subfamilia(s), ${tests} registro(s) de ensayo y ${regCount} ficha(s) normativa(s) disponibles para esta línea.
          ${isReg ? ' En RETIE/RETILAP se muestran artículos, documentos, esquemas, NACE y observaciones; los ensayos se vincularán cuando cargues la matriz técnica.' : ''}
          ${(!tests && !isReg) ? ' Esta línea ya queda creada para cargar su matriz en una siguiente fase.' : ''}
        </div>
      `;

      const pendingNotice = $('pendingMatrixNotice');
      if (pendingNotice) {
        pendingNotice.style.display = isReg ? 'none' : (subfamilies && !tests ? 'block' : 'none');
      }
      const regulatoryImportPanel = $('regulatoryImportPanel');
      if (regulatoryImportPanel) {
        regulatoryImportPanel.style.display = isReg ? 'block' : 'none';
        renderRegulatoryImportSummary();
      }
      const phaseFilter = $('phaseFilter');
      if (phaseFilter) phaseFilter.disabled = isReg;
    }

    function renderClassSelect() {
      if (isRegulatoryLine()) {
        $('classComboSelect').innerHTML = '<option value="">RETIE/RETILAP no usa combinaciones automáticas</option>';
        $('subComboSelect').innerHTML = '<option value="">Selecciona productos desde la lista manual</option>';
        $('classComboInfo').innerHTML = '<strong>Modo producto/artículo</strong><br>Selecciona uno o varios productos. No se generan combinaciones raras.';
        $('subComboInfo').innerHTML = '<span class="muted">La ficha normativa se calcula producto por producto.</span>';
        return;
      }

      const firstCombos = [...combosByClass.entries()]
        .map(([id, list]) => list.find(belongsToCurrentLine))
        .filter(Boolean);
      firstCombos.sort((a, b) => collator.compare(a.idClasificacion, b.idClasificacion));

      if (!firstCombos.length) {
        $('classComboSelect').innerHTML = '<option value="">Sin combinaciones para esta línea</option>';
        updateSubcomboSelect();
        return;
      }

      $('classComboSelect').innerHTML = firstCombos.map(combo => {
        const label = combo.classFamilies.map(familyLabel).join(' + ');
        const count = (combosByClass.get(combo.idClasificacion) || []).filter(belongsToCurrentLine).length;
        return `<option value="${escapeHtml(combo.idClasificacion)}">${escapeHtml(combo.idClasificacion)} · ${escapeHtml(label)} (${count})</option>`;
      }).join('');

      updateSubcomboSelect();
    }

    function renderFamilySelect() {
      const families = [...subfamiliesByFamily.entries()]
        .filter(([, subs]) => subs.some(belongsToCurrentLine))
        .map(([family]) => family)
        .sort((a, b) => collator.compare(familyLabel(a), familyLabel(b)));
      $('familySelect').innerHTML = families.map(fam => `<option value="${escapeHtml(fam)}">${escapeHtml(familyLabel(fam))}</option>`).join('');
      renderSubfamilyChecks();
    }

    function updateSubcomboSelect() {
      const classId = $('classComboSelect').value;
      const list = (combosByClass.get(classId) || []).filter(belongsToCurrentLine);
      const current = list[0];

      $('classComboInfo').innerHTML = current
        ? `<strong>${escapeHtml(current.idClasificacion)}</strong><br>${escapeHtml(current.classFamilies.map(familyLabel).join(' + '))}<div class="mini">${list.length} subcombinaciones disponibles para esta clasificación.</div>`
        : '<span class="muted">Selecciona una clasificación.</span>';

      $('subComboSelect').innerHTML = list.map(combo => {
        const label = combo.subfamilies.map(subLabel).join(' + ');
        return `<option value="${escapeHtml(combo.idSubcombinacion)}">${escapeHtml(combo.idSubcombinacion)} · ${escapeHtml(label)}</option>`;
      }).join('');

      updateSubcomboInfo();
    }

    function selectedSubcombo() {
      const classId = $('classComboSelect').value;
      const subId = $('subComboSelect').value;
      return (combosByClass.get(classId) || []).filter(belongsToCurrentLine).find(item => item.idSubcombinacion === subId);
    }

    function updateSubcomboInfo() {
      const combo = selectedSubcombo();
      if (!combo) {
        $('subComboInfo').innerHTML = '<span class="muted">Sin subcombinación seleccionada.</span>';
        return;
      }

      const countLine = [
        `Total: ${combo.counts.total}`,
        `OT: ${combo.counts.OT}`,
        `VIG 1: ${combo.counts.VIG_1}`,
        `VIG 2: ${combo.counts.VIG_2}`,
        `Renovación: ${combo.counts.RENOVACION}`
      ].join(' · ');

      $('subComboInfo').innerHTML = `
        <strong>${escapeHtml(combo.idSubcombinacion)}</strong><br>
        ${escapeHtml(combo.subfamilies.map(subLabel).join(' + '))}
        <div class="pill-list">
          ${combo.subfamilies.map(sub => `<span class="pill">${escapeHtml(subLabel(sub))}</span>`).join('')}
        </div>
        <div class="mini" style="margin-top:.6rem;">Ensayos precontados en matriz: ${escapeHtml(countLine)}</div>
      `;
    }

    function renderSubfamilyChecks() {
      const fam = $('familySelect').value;
      const subs = (subfamiliesByFamily.get(fam) || []).filter(belongsToCurrentLine);

      $('subfamilyChecks').innerHTML = subs.map(item => `
        <label class="check-card">
          <input type="checkbox" value="${escapeHtml(item.subfamiliaNorm)}">
          <span>
            <strong>${escapeHtml(item.subfamilia)}</strong>
            <span>${escapeHtml(item.cantidadEnsayosBase)} ensayos base · ${escapeHtml(item.familia)}</span>
          </span>
        </label>
      `).join('') || '<div class="empty">No hay subfamilias para esta familia.</div>';
    }

    function addSubfamiliesToCurrent(subfamilies, sourceLabel = 'selección') {
      const before = state.currentToy.subfamilies.length;
      const set = new Set(state.currentToy.subfamilies);
      subfamilies.filter(Boolean).forEach(sub => set.add(sub));
      state.currentToy.subfamilies = [...set].sort((a, b) => collator.compare(subLabel(a), subLabel(b)));
      const added = state.currentToy.subfamilies.length - before;
      renderCurrentToy();
      persistState();
      showToast(added ? `${added} subfamilia(s) agregada(s) desde ${sourceLabel}.` : 'Estas subfamilias ya estaban agregadas.');
    }

    function renderCurrentToy() {
      const input = $('toyNameInput');
      if (document.activeElement !== input) {
        input.value = state.currentToy.name || defaultToyName();
      }

      $('currentToyCount').textContent = `${state.currentToy.subfamilies.length} subfamilia(s)`;

      if (!state.currentToy.subfamilies.length) {
        $('currentToyChips').innerHTML = '<div class="empty">Todavía no has agregado subfamilias al ítem actual.</div>';
        return;
      }

      $('currentToyChips').innerHTML = state.currentToy.subfamilies.map(sub => `
        <span class="pill">
          ${escapeHtml(subLabel(sub))}
          <button type="button" title="Quitar" data-remove-sub="${escapeHtml(sub)}">×</button>
        </span>
      `).join('');
    }

    function defaultToyName() {
      return `Ítem ${state.savedToys.length + 1}`;
    }

    function saveCurrentToy() {
      const name = $('toyNameInput').value.trim() || defaultToyName();

      if (!state.currentToy.subfamilies.length) {
        showToast('Agrega al menos una subfamilia antes de guardar el ítem.');
        return;
      }

      state.savedToys.push({
        id: state.currentToy.id,
        name,
        subfamilies: [...state.currentToy.subfamilies]
      });

      state.currentToy = newToy(`Juguete ${state.savedToys.length + 1}`);
      renderCurrentToy();
      renderSavedToys();
      persistState();
      showToast('Juguete guardado en la lista.');
    }

    function renderSavedToys() {
      if (!state.savedToys.length) {
        $('savedToys').innerHTML = '<div class="empty">Aún no hay juguetes guardados. Puedes calcular también con el juguete actual si tiene componentes.</div>';
        return;
      }

      $('savedToys').innerHTML = state.savedToys.map(toy => {
        const chips = toy.subfamilies.slice(0, 8).map(sub => `<span class="pill neutral">${escapeHtml(subLabel(sub))}</span>`).join('');
        const rest = toy.subfamilies.length > 8 ? `<span class="pill neutral">+${toy.subfamilies.length - 8} más</span>` : '';
        return `
          <article class="toy-card">
            <header>
              <div>
                <h3>${escapeHtml(toy.name)}</h3>
                <small>${toy.subfamilies.length} subfamilia(s)</small>
              </div>
            </header>
            <div class="pill-list">${chips}${rest}</div>
            <div class="actions">
              <button type="button" class="secondary" data-load-toy="${escapeHtml(toy.id)}">Cargar copia</button>
              <button type="button" class="ghost" data-delete-toy="${escapeHtml(toy.id)}">Eliminar</button>
            </div>
          </article>
        `;
      }).join('');
    }

    function toysForCalculation() {
      const toys = state.savedToys.map(toy => ({
        id: toy.id,
        name: toy.name,
        subfamilies: [...toy.subfamilies]
      }));

      if (state.currentToy.subfamilies.length) {
        toys.push({
          id: state.currentToy.id,
          name: $('toyNameInput').value.trim() || state.currentToy.name || 'Ítem actual',
          subfamilies: [...state.currentToy.subfamilies]
        });
      }

      return toys;
    }


    function calculateRegulatoryResults() {
      const toys = toysForCalculation();

      if (!toys.length) {
        state.results = [];
        state.metrics = null;
        renderResults();
        showToast('Agrega o guarda al menos un producto para generar la ficha normativa.');
        return;
      }

      const aggregated = new Map();
      let sourceRows = 0;
      const uniqueSubfamilies = new Set();

      toys.forEach(toy => {
        uniqueSorted(toy.subfamilies).forEach(sub => {
          uniqueSubfamilies.add(sub);
          const records = regulatoryRecordsForSubfamily(sub);

          if (!records.length) {
            const key = normalizeKey([currentProductLine(), subLabel(sub)].join('|'));
            if (!aggregated.has(key)) {
              aggregated.set(key, {
                type: 'regulatory',
                key,
                producto: subLabel(sub),
                clase: currentProductLine(),
                familia: familyLabel(sub),
                familiaArticulo: '',
                subfamilia: subLabel(sub),
                articuloAdicional: 'Sin ficha normativa importada todavía.',
                articuloEnsayosMinimos: '',
                documento: '',
                esquemas: [],
                codigoNace: '',
                nace: '',
                juguetes: new Set()
              });
            }
            aggregated.get(key).juguetes.add(toy.name);
            return;
          }

          records.forEach(record => {
            sourceRows += 1;
            const key = normalizeKey([record.clase, record.producto, record.subfamilia, record.articuloEnsayosMinimos].join('|'));

            if (!aggregated.has(key)) {
              aggregated.set(key, {
                type: 'regulatory',
                key,
                producto: record.producto || record.subfamilia,
                clase: record.clase,
                familia: record.familia,
                familiaArticulo: record.familiaArticulo,
                subfamilia: record.subfamilia,
                articuloAdicional: record.articuloAdicional,
                articuloEnsayosMinimos: record.articuloEnsayosMinimos,
                documento: record.documento,
                esquemas: new Set(record.esquemas || []),
                codigoNace: record.codigoNace,
                nace: record.nace,
                juguetes: new Set()
              });
            }

            const row = aggregated.get(key);
            (record.esquemas || []).forEach(esquema => row.esquemas.add(esquema));
            if (!row.codigoNace && record.codigoNace) row.codigoNace = record.codigoNace;
            if (!row.nace && record.nace) row.nace = record.nace;
            row.juguetes.add(toy.name);
          });
        });
      });

      const results = [...aggregated.values()]
        .map(row => ({
          ...row,
          esquemas: uniqueSorted([...(row.esquemas || [])]),
          juguetes: uniqueSorted([...row.juguetes])
        }))
        .sort((a, b) => collator.compare(a.producto, b.producto));

      state.results = results;
      state.metrics = {
        mode: 'regulatory',
        toys: toys.length,
        selectedSubfamilies: uniqueSubfamilies.size,
        uniqueEssays: results.length,
        sourceRows,
        duplicatesRemoved: Math.max(0, sourceRows - results.length),
        phaseCounts: { OT: 0, VIG_1: 0, VIG_2: 0, RENOVACION: 0 }
      };

      renderToyFilter(toys);
      renderResults();
      persistState();
      showToast(`${results.length} ficha(s) normativa(s) consolidada(s).`);
    }

    function calculateResults() {
      if (isRegulatoryLine()) {
        calculateRegulatoryResults();
        return;
      }

      const toys = toysForCalculation();

      if (!toys.length) {
        state.results = [];
        state.metrics = null;
        renderResults();
        showToast('Agrega o guarda al menos un ítem para calcular ensayos.');
        return;
      }

      const aggregated = new Map();
      let sourceRows = 0;
      const uniqueSubfamilies = new Set();

      toys.forEach(toy => {
        uniqueSorted(toy.subfamilies).forEach(sub => {
          uniqueSubfamilies.add(sub);
          const tests = testsBySubfamily.get(sub) || [];

          tests.forEach(test => {
            if (!test.ensayo) return;
            sourceRows += 1;
            const key = normalizeKey(test.ensayo);

            if (!aggregated.has(key)) {
              aggregated.set(key, {
                key,
                ensayo: test.ensayo,
                literales: new Set(),
                normas: new Set(),
                subfamilias: new Set(),
                familias: new Set(),
                filasFuente: new Set(),
                juguetes: new Set(),
                OT: false,
                VIG_1: false,
                VIG_2: false,
                RENOVACION: false
              });
            }

            const row = aggregated.get(key);
            if (test.literal) row.literales.add(test.literal);
            if (test.norma) row.normas.add(test.norma);
            if (test.subfamiliaNorm) row.subfamilias.add(subLabel(test.subfamiliaNorm));
            if (test.familiaNorm) row.familias.add(familyLabel(test.familiaNorm));
            if (test.filaFuente) row.filasFuente.add(String(test.filaFuente));
            row.juguetes.add(toy.name);
            PHASES.forEach(p => {
              row[p.key] = row[p.key] || Boolean(test[p.key]);
            });
          });
        });
      });

      const results = [...aggregated.values()]
        .map(row => ({
          ...row,
          literales: uniqueSorted([...row.literales]),
          normas: uniqueSorted([...row.normas]),
          subfamilias: uniqueSorted([...row.subfamilias]),
          familias: uniqueSorted([...row.familias]),
          filasFuente: uniqueSorted([...row.filasFuente]),
          juguetes: uniqueSorted([...row.juguetes])
        }))
        .sort((a, b) => collator.compare(a.ensayo, b.ensayo));

      const phaseCounts = Object.fromEntries(PHASES.map(p => [p.key, results.filter(row => row[p.key]).length]));

      state.results = results;
      state.metrics = {
        toys: toys.length,
        selectedSubfamilies: uniqueSubfamilies.size,
        sourceRows,
        uniqueEssays: results.length,
        duplicatesRemoved: Math.max(sourceRows - results.length, 0),
        phaseCounts
      };

      renderToyFilter(toys);
      renderResults();
      showToast(`${results.length} ensayo(s) único(s) calculado(s).`);
      $('resultsPanel').scrollIntoView({ behavior: 'smooth', block: 'start' });
    }

    function renderToyFilter(toys = toysForCalculation()) {
      const names = uniqueSorted(toys.map(toy => toy.name));
      $('toyFilter').innerHTML = '<option value="ALL">Todos los ítems</option>' + names.map(name => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('');
    }

    function filteredResults() {
      const query = normalizeKey($('searchInput').value);
      const phase = $('phaseFilter').value;
      const toy = $('toyFilter').value;
      const regMode = state.metrics?.mode === 'regulatory';

      return state.results.filter(row => {
        if (!regMode && phase !== 'ALL' && !row[phase]) return false;
        if (toy !== 'ALL' && !row.juguetes.includes(toy)) return false;

        if (query) {
          const haystack = regMode
            ? normalizeKey([
                row.producto,
                row.familia,
                row.familiaArticulo,
                row.subfamilia,
                row.articuloAdicional,
                row.articuloEnsayosMinimos,
                row.documento,
                (row.esquemas || []).join(' '),
                row.codigoNace,
                row.nace,
                row.juguetes.join(' ')
              ].join(' '))
            : normalizeKey([
                row.ensayo,
                row.literales.join(' '),
                row.normas.join(' '),
                row.subfamilias.join(' '),
                row.familias.join(' '),
                row.juguetes.join(' ')
              ].join(' '));
          if (!haystack.includes(query)) return false;
        }

        return true;
      });
    }

    function renderResultStats(filtered = filteredResults()) {
      const m = state.metrics;
      if (!m) {
        $('resultStats').innerHTML = '';
        return;
      }

      const regMode = m.mode === 'regulatory';
      const items = regMode ? [
        [m.toys, 'ítems/productos evaluados'],
        [m.selectedSubfamilies, 'productos seleccionados'],
        [m.uniqueEssays, 'fichas normativas únicas'],
        [m.sourceRows, 'registros normativos usados'],
        [m.duplicatesRemoved, 'duplicados consolidados']
      ] : [
        [m.toys, 'ítems evaluados'],
        [m.selectedSubfamilies, 'subfamilias únicas'],
        [m.uniqueEssays, 'ensayos sin repetir'],
        [m.sourceRows, 'registros fuente usados'],
        [m.duplicatesRemoved, 'duplicados consolidados']
      ];

      $('resultStats').innerHTML = items.map(([value, label]) => `
        <div class="result-stat">
          <strong>${escapeHtml(value)}</strong>
          <span>${escapeHtml(label)}</span>
        </div>
      `).join('') + `
        <div class="result-stat">
          <strong>${escapeHtml(filtered.length)}</strong>
          <span>${regMode ? 'fichas visibles con filtros' : 'ensayos visibles con filtros'}</span>
        </div>
        ${regMode ? '' : PHASES.map(p => `
          <div class="result-stat">
            <strong>${escapeHtml(m.phaseCounts[p.key] || 0)}</strong>
            <span>${escapeHtml(p.label)}</span>
          </div>
        `).join('')}
      `;
    }

    function renderResults() {
      const rows = filteredResults();
      const regMode = state.metrics?.mode === 'regulatory' || isRegulatoryLine();
      renderResultStats(rows);

      if (regMode) {
        $('resultsHead').innerHTML = `
          <tr>
            <th>#</th>
            <th>Producto</th>
            <th>Artículo / numeral</th>
            <th>Familia / subfamilia</th>
            <th>Observación adicional</th>
            <th>Documento</th>
            <th>Esquemas / Código NACE</th>
            <th>Ítems</th>
          </tr>
        `;
      } else {
        $('resultsHead').innerHTML = `
          <tr>
            <th>#</th>
            <th>Ensayo único</th>
            <th>Literal / numeral</th>
            <th>Norma técnica</th>
            <th>Fases</th>
            <th>Fuentes</th>
            <th>Ítems</th>
          </tr>
        `;
      }

      if (!state.metrics) {
        $('resultHint').textContent = regMode
          ? 'Agrega al menos un producto y presiona “Calcular”. Se mostrará artículo, documento, esquemas, NACE y observaciones.'
          : 'Agrega al menos un ítem y presiona “Calcular ensayos sin repetir”.';
      } else {
        $('resultHint').textContent = regMode
          ? `Resultado calculado con ${state.metrics.toys} ítem(s). La tabla consolida fichas normativas sin combinar productos entre sí.`
          : `Resultado calculado con ${state.metrics.toys} ítem(s). La tabla elimina duplicados por ensayo y agrupa fuentes.`;
      }

      if (!rows.length) {
        const message = state.results.length
          ? (regMode ? 'No hay fichas que coincidan con los filtros.' : 'No hay ensayos que coincidan con los filtros.')
          : 'Sin resultados calculados.';
        $('resultsBody').innerHTML = `<tr><td colspan="${regMode ? 8 : 7}" class="empty">${message}</td></tr>`;
        return;
      }

      if (regMode) {
        $('resultsBody').innerHTML = rows.map((row, index) => `
          <tr>
            <td>${index + 1}</td>
            <td>
              <div class="essay-name">${escapeHtml(row.producto || '—')}</div>
              <div class="mini">${escapeHtml(productLineLabel(row.clase || currentProductLine()))}</div>
            </td>
            <td>
              <strong>${escapeHtml(row.articuloEnsayosMinimos || '—')}</strong>
              <div class="mini">${escapeHtml(row.familiaArticulo || '')}</div>
            </td>
            <td>
              <strong>${escapeHtml(row.familia || '—')}</strong>
              <div class="mini">${escapeHtml(row.subfamilia || '')}</div>
            </td>
            <td>${row.articuloAdicional ? escapeHtml(row.articuloAdicional) : '<span class="muted">—</span>'}</td>
            <td>${row.documento ? escapeHtml(row.documento) : '<span class="muted">—</span>'}</td>
            <td>
              <strong>Esquemas:</strong><br>${joinSmall(row.esquemas, ' | ')}
              <div class="mini"><strong>Código NACE:</strong> ${escapeHtml(row.codigoNace || '—')}</div>
              <div class="mini"><strong>NACE:</strong> ${escapeHtml(row.nace || '—')}</div>
            </td>
            <td>${joinSmall(row.juguetes, ' | ')}</td>
          </tr>
        `).join('');
        return;
      }

      $('resultsBody').innerHTML = rows.map((row, index) => `
        <tr>
          <td>${index + 1}</td>
          <td>
            <div class="essay-name">${escapeHtml(row.ensayo)}</div>
            <div class="mini">Filas fuente: ${joinSmall(row.filasFuente, ' | ')}</div>
          </td>
          <td>${joinSmall(row.literales, ' | ')}</td>
          <td>${joinSmall(row.normas, ' | ')}</td>
          <td><div class="pill-list">${phaseBadges(row)}</div></td>
          <td>
            <strong>Subfamilias:</strong><br>${joinSmall(row.subfamilias, ' | ')}
            <div class="mini"><strong>Familias:</strong> ${joinSmall(row.familias, ' | ')}</div>
          </td>
          <td>${joinSmall(row.juguetes, ' | ')}</td>
        </tr>
      `).join('');
    }

    function exportRows() {
      const regMode = state.metrics?.mode === 'regulatory';
      if (regMode) {
        return filteredResults().map((row, index) => ({
          "#": index + 1,
          "Producto": row.producto,
          "Línea de producto": productLineLabel(row.clase || currentProductLine()),
          "Familia": row.familia,
          "Familia artículo": row.familiaArticulo,
          "Subfamilia": row.subfamilia,
          "Artículo adicional / observación": row.articuloAdicional,
          "Artículo ensayos mínimos": row.articuloEnsayosMinimos,
          "Documento": row.documento,
          "Esquemas": (row.esquemas || []).join(' | '),
          "Código NACE": row.codigoNace,
          "NACE": row.nace,
          "Ítems": row.juguetes.join(' | ')
        }));
      }

      return filteredResults().map((row, index) => ({
        "#": index + 1,
        "Ensayo único": row.ensayo,
        "Literal / numeral": row.literales.join(' | '),
        "Norma técnica": row.normas.join(' | '),
        "Fases": PHASES.filter(p => row[p.key]).map(p => p.label).join(' | '),
        "Subfamilias fuente": row.subfamilias.join(' | '),
        "Familias fuente": row.familias.join(' | '),
        "Ítems": row.juguetes.join(' | '),
        "Filas fuente": row.filasFuente.join(' | ')
      }));
    }

    function downloadBlob(filename, content, type) {
      const blob = new Blob([content], { type });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    }

    function exportCsv() {
      const rows = exportRows();
      if (!rows.length) {
        showToast('No hay resultados para exportar.');
        return;
      }
      const headers = Object.keys(rows[0]);
      const csv = [
        headers.join(';'),
        ...rows.map(row => headers.map(h => csvCell(row[h])).join(';'))
      ].join('\n');
      downloadBlob((state.metrics?.mode === 'regulatory' ? 'fichas_normativas_retie_retilap.csv' : 'ensayos_sin_repetir.csv'), '\ufeff' + csv, 'text/csv;charset=utf-8');
    }

    function csvCell(value) {
      const text = String(value ?? '');
      if (/[;"\n\r]/.test(text)) return `"${text.replaceAll('"', '""')}"`;
      return text;
    }

    function exportJson() {
      const payload = {
        generadoEn: new Date().toISOString(),
        meta: DATA.meta,
        metricas: state.metrics,
        proyecto: state.project,
        items: toysForCalculation(),
        resultados: exportRows()
      };
      downloadBlob((state.metrics?.mode === 'regulatory' ? 'fichas_normativas_retie_retilap.json' : 'ensayos_sin_repetir.json'), JSON.stringify(payload, null, 2), 'application/json;charset=utf-8');
    }

    function resetCurrentToy() {
      state.currentToy = newToy(defaultToyName());
      renderCurrentToy();
      persistState();
      showToast('Constructor listo para un nuevo ítem.');
    }

    function clearAll() {
      const ok = confirm('¿Seguro que quieres limpiar ítems, constructor y resultados?');
      if (!ok) return;

      state.currentToy = newToy('Ítem 1');
      state.savedToys = [];
      state.results = [];
      state.metrics = null;
      localStorage.removeItem(STORAGE_KEY);
      renderCurrentToy();
      renderSavedToys();
      renderToyFilter([]);
      renderResults();
      showToast('Proyecto limpiado.');
    }

    function showToast(message) {
      const toast = $('toast');
      toast.textContent = message;
      toast.classList.add('show');
      window.clearTimeout(showToast.timer);
      showToast.timer = window.setTimeout(() => toast.classList.remove('show'), 2600);
    }

    function bindEvents() {
      $('referenceTypeSelect').addEventListener('change', () => {
        state.project.referenceType = $('referenceTypeSelect').value;
        renderProjectConfig();
        persistState();
      });

      $('productLineSelect').addEventListener('change', () => {
        state.project.productLine = $('productLineSelect').value;
        state.results = [];
        state.metrics = null;
        renderProjectConfig();
        renderClassSelect();
        renderFamilySelect();
        renderResults();
        persistState();
        showToast('Línea de producto actualizada.');
      });

      $('projectNameInput').addEventListener('input', () => {
        state.project.projectName = $('projectNameInput').value.trim();
        persistState();
      });

      $('classComboSelect').addEventListener('change', updateSubcomboSelect);
      $('subComboSelect').addEventListener('change', updateSubcomboInfo);
      $('familySelect').addEventListener('change', renderSubfamilyChecks);

      $('loadSubcomboBtn').addEventListener('click', () => {
        const combo = selectedSubcombo();
        if (!combo) return;
        addSubfamiliesToCurrent(combo.subfamilies, combo.idSubcombinacion);
      });

      $('saveSubcomboToyBtn').addEventListener('click', () => {
        const combo = selectedSubcombo();
        if (!combo) return;
        const toy = {
          id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),
          name: combo.idSubcombinacion,
          subfamilies: uniqueSorted(combo.subfamilies)
        };
        state.savedToys.push(toy);
        renderSavedToys();
        persistState();
        showToast(`${combo.idSubcombinacion} guardado como ítem.`);
      });

      $('addManualBtn').addEventListener('click', () => {
        const selected = [...$('subfamilyChecks').querySelectorAll('input:checked')].map(input => input.value);
        if (!selected.length) {
          showToast('Marca al menos una subfamilia.');
          return;
        }
        addSubfamiliesToCurrent(selected, 'selección manual');
      });

      $('clearChecksBtn').addEventListener('click', () => {
        $('subfamilyChecks').querySelectorAll('input:checked').forEach(input => input.checked = false);
      });

      $('toyNameInput').addEventListener('input', () => {
        state.currentToy.name = $('toyNameInput').value;
        persistState();
      });

      $('currentToyChips').addEventListener('click', (event) => {
        const sub = event.target?.dataset?.removeSub;
        if (!sub) return;
        state.currentToy.subfamilies = state.currentToy.subfamilies.filter(item => item !== sub);
        renderCurrentToy();
        persistState();
      });

      $('saveCurrentToyBtn').addEventListener('click', saveCurrentToy);
      $('resetCurrentBtn').addEventListener('click', resetCurrentToy);
      $('calculateBtn').addEventListener('click', calculateResults);
      $('clearAllBtn').addEventListener('click', clearAll);

      $('savedToys').addEventListener('click', (event) => {
        const deleteId = event.target?.dataset?.deleteToy;
        const loadId = event.target?.dataset?.loadToy;

        if (deleteId) {
          state.savedToys = state.savedToys.filter(toy => toy.id !== deleteId);
          renderSavedToys();
          persistState();
          showToast('Juguete eliminado.');
        }

        if (loadId) {
          const toy = state.savedToys.find(item => item.id === loadId);
          if (!toy) return;
          state.currentToy = {
            id: crypto.randomUUID ? crypto.randomUUID() : String(Date.now() + Math.random()),
            name: `${toy.name} (copia)`,
            subfamilies: [...toy.subfamilies]
          };
          renderCurrentToy();
          persistState();
          showToast('Copia cargada en el constructor.');
        }
      });

      ['searchInput', 'phaseFilter', 'toyFilter'].forEach(id => {
        $(id).addEventListener('input', renderResults);
        $(id).addEventListener('change', renderResults);
      });


      if ($('importRegulatoryBtn')) {
        $('importRegulatoryBtn').addEventListener('click', () => {
          const text = $('regulatoryPasteInput').value;
          const records = parseRegulatoryTable(text);
          if (!records.length) {
            showToast('No se detectaron registros. Verifica que pegaste la tabla con encabezados.');
            return;
          }
          saveImportedRegulatoryRecords(records);
          initMaps();
          renderProjectConfig();
          renderFamilySelect();
          renderClassSelect();
          renderResults();
          $('regulatoryPasteInput').value = '';
          showToast(`${records.length} registro(s) RETIE/RETILAP importado(s).`);
        });
      }

      if ($('clearRegulatoryImportBtn')) {
        $('clearRegulatoryImportBtn').addEventListener('click', () => {
          const ok = confirm('¿Seguro que quieres borrar la base RETIE/RETILAP importada en este navegador?');
          if (!ok) return;
          localStorage.removeItem(REGULATORY_STORAGE_KEY);
          loadRegulatoryRecords();
          initMaps();
          renderProjectConfig();
          renderFamilySelect();
          renderClassSelect();
          renderResults();
          showToast('Base importada limpiada.');
        });
      }

      $('exportCsvBtn').addEventListener('click', exportCsv);
      $('exportJsonBtn').addEventListener('click', exportJson);
      $('printBtn').addEventListener('click', () => window.print());
    }

    function init() {
      loadRegulatoryRecords();
      initMaps();
      loadState();
      renderStats();
      renderProjectConfig();
      renderClassSelect();
      renderFamilySelect();
      renderCurrentToy();
      renderSavedToys();
      renderToyFilter();
      renderResults();
      bindEvents();
    }

    init();
  </script>
</body>
</html>
